class Solution:
    def sortPermutation(self, nums: List[int]) -> int:
        k = -1
        for i, v in enumerate(nums):
            if v != i:
                k = v if k < 0 else k & v
        return max(k, 0)

c.cpp:
class Solution {
public:
    int sortPermutation(vector<int>& nums) {
        int k = -1;
        for (int i = 0; i < (int)nums.size(); i++)
            if (nums[i] != i) k = (k < 0) ? nums[i] : (k & nums[i]);
        return max(k, 0);
    }
};

