class Solution {
    public int sortPermutation(int[] nums) {
        int k = -1;
        for (int i = 0; i < nums.length; i++)
            if (nums[i] != i) k = (k < 0) ? nums[i] : (k & nums[i]);
        return Math.max(k, 0);
    }
}

